create table if not exists public.platform_integration_settings(
 id uuid primary key default gen_random_uuid(),provider text not null unique,environment text not null default 'SANDBOX',api_base_url text,client_id text,secret_ref text,webhook_url text,webhook_secret_ref text,enabled boolean not null default false,last_validation_at timestamptz,last_validation_status text,notes text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
alter table public.platform_integration_settings enable row level security;
revoke all on public.platform_integration_settings from anon,authenticated;
create or replace function public.get_platform_integration_settings() returns setof public.platform_integration_settings language plpgsql stable security definer set search_path='public','private','auth' as $$ begin if auth.uid() is null or not private.is_super_admin() then raise exception 'forbidden'; end if; return query select * from public.platform_integration_settings order by provider; end $$;
revoke all on function public.get_platform_integration_settings() from public,anon; grant execute on function public.get_platform_integration_settings() to authenticated;
create or replace function public.save_platform_integration_setting(p_payload jsonb) returns uuid language plpgsql security definer set search_path='public','private','auth' as $$ declare v_id uuid;v_provider text:=upper(trim(coalesce(p_payload->>'provider',''))); begin if auth.uid() is null or not private.is_super_admin() then raise exception 'forbidden'; end if;if v_provider not in ('ASAAS') then raise exception 'provider not allowed';end if;insert into public.platform_integration_settings(provider,environment,api_base_url,client_id,secret_ref,webhook_url,webhook_secret_ref,enabled,notes,updated_at) values(v_provider,upper(coalesce(p_payload->>'environment','SANDBOX')),nullif(p_payload->>'api_base_url',''),nullif(p_payload->>'client_id',''),nullif(p_payload->>'secret_ref',''),nullif(p_payload->>'webhook_url',''),nullif(p_payload->>'webhook_secret_ref',''),coalesce((p_payload->>'enabled')::boolean,false),nullif(p_payload->>'notes',''),now()) on conflict(provider) do update set environment=excluded.environment,api_base_url=excluded.api_base_url,client_id=excluded.client_id,secret_ref=excluded.secret_ref,webhook_url=excluded.webhook_url,webhook_secret_ref=excluded.webhook_secret_ref,enabled=excluded.enabled,notes=excluded.notes,updated_at=now() returning id into v_id;return v_id;end $$;
revoke all on function public.save_platform_integration_setting(jsonb) from public,anon;grant execute on function public.save_platform_integration_setting(jsonb) to authenticated;